def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    from collections import defaultdict

    # Create a grid filled with zeros
    grid = defaultdict(lambda: defaultdict(int))

    # Fill the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0:
            break
        grid[x-1][y-1] = value

    # Initialize DP tables
    dp1 = [[0 for _ in range(N)] for _ in range(N)]
    dp2 = [[0 for _ in range(N)] for _ in range(N)]

    # Directions for movement (right, down)
    directions = [(0, 1), (1, 0)]

    # Fill the first DP table to the right and down
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                dp1[i][j] = grid[i][j]
            else:
                dp1[i][j] = dp1[i-1][j] + dp1[i][j-1]

    # Fill the second DP table to the right and down
    for i in range(N-1, -1, -1):
        for j in range(N-1, -1, -1):
            if i == N-1 and j == N-1:
                dp2[i][j] = grid[i][j]
            else:
                dp2[i][j] = max(dp2[i+1][j], dp2[i][j+1])

    # The maximum sum of values collected on the two paths
    result = 0
    for i in range(N):
        for j in range(N):
            if i == j == 0:
                continue
            result = max(result, dp1[i][j] + dp2[i][j] - grid[i][j])

    return result

