def cantor_numbering(N: int) -> str:
    if N <= 0:
        raise ValueError("N must be a positive integer")

    if N == 1:
        return "1/1"

    diagonal = 1
    while N > 1:
        if N > diagonal:
            N -= diagonal
            diagonal += 1
        else:
            if diagonal % 2 == 0:
                numerator = diagonal - N + 1
                denominator = N
            else:
                numerator = N
                denominator = diagonal - N + 1
            return f"{numerator}/{denominator}"

def max_product(num_str: str, N: int, K: int) -> int:
    import functools
    import operator

    if not num_str or N != len(num_str) or K < 0:
        raise ValueError("Invalid input")

    num_list = [int(digit) for digit in num_str]
    num_len = len(num_list)

    if K >= num_len - 1:
        return functools.reduce(operator.mul, num_list)

    max_product = 0

    def dfs(start, product, count):
        nonlocal max_product
        if count == K:
            max_product = max(max_product, product)
            return
        for i in range(start, num_len):
            dfs(i + 1, product * num_list[i], count + 1)

    dfs(0, 1, 0)

    return max_product

