def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        total = 0
        for i, char in enumerate(isbn.replace('-', '')):
            if char.isdigit():
                total += (10 if char == 'X' else int(char)) * (10 - i)
            else:
                return -1  # Invalid character
        return total % 11

    # Remove hyphens and calculate the current checksum
    base_isbn = isbn.replace('-', '')
    current_checksum = calculate_checksum(base_isbn)

    # If the ISBN is already valid
    if current_checksum == 0:
        return "Right"

    # Try to correct the ISBN by replacing the last character with digits 0-9 and X
    for i in range(10):
        test_isbn = base_isbn[:-1] + str(i if i != 10 else 'X')
        if calculate_checksum(test_isbn) == 0:
            return isbn[:-1] + str(i if i != 10 else 'X')

    # If no correction is possible, return the original ISBN
    return isbn

