def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("Invalid input: n must be a positive integer and m must be a non-negative integer.")

    # Initialize a 2D array to store the number of ways to pass the ball
    dp = [[0] * (m + 1) for _ in range(n)]

    # Base cases: There's only one way to pass the ball to the left or right neighbor on the first pass
    for i in range(n):
        dp[i][1] = 1

    # Fill the DP table
    for i in range(n):
        for j in range(2, m + 1):
            dp[i][j] = dp[(i - 1) % n][j - 1] + dp[(i + 1) % n][j - 1]

    # The result is the number of ways to pass the ball back to the starting student after m passes
    return dp[0][m]

def max_energy(beads):
    n = len(beads)
    if n < 3:
        return 0

    # Create a table to store the maximum energy obtainable for each subarray
    dp = [[0] * n for _ in range(n)]

    # Initialize the table for single bead merges
    for i in range(n):
        dp[i][i] = 0

    # Fill the table for subarrays of increasing length
    for length in range(2, n + 1):
        for i in range(n):
            j = (i + length - 1) % n
            dp[i][j] = max(dp[i][k] + dp[(k + 1) % n][j] + beads[i] * beads[k] * beads[j] for k in range(i + 1, j))

    return dp[0][n - 1]

