def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[i]
        if coeff == 0:
            continue
        if i == 0:
            term = f"{abs(coeff)}"
        elif i == 1:
            if coeff == 1:
                term = 'x'
            elif coeff == -1:
                term = '-x'
            else:
                term = f"{abs(coeff)}x"
        else:
            if coeff == 1:
                term = f"x^{i}"
            elif coeff == -1:
                term = f"-x^{i}"
            else:
                term = f"{abs(coeff)}x^{i}"
        terms.append(term)
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping and mapping[e] != o:
            return "Failed"
        mapping[e] = o

    decoded_message = []
    for char in message:
        if char in mapping:
            decoded_message.append(mapping[char])
        else:
            return "Failed"

    return ''.join(decoded_message)

def largest_prime_factor(n: int) -> int:
    if n <= 1:
        raise ValueError("Input must be a positive integer greater than 1")

    # Check for smallest prime factor 2
    if n % 2 == 0:
        return n // 2

    # Check for odd factors from 3 onwards
    factor = 3
    while factor * factor <= n:
        if n % factor == 0:
            return n // factor
        factor += 2

    # If no factors found, n is a prime number and is the largest factor
    return n

def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x:
        return 0
    if k == 1:
        return 1
    return sum(count_partitions(n - i, k - 1, i) for i in range(x, n // k + 1))

def count_sequences(n: int, last: int, memo: dict) -> int:
    if n <= 0:
        return 0
    if last in memo:
        return memo[last]
    count = 0
    for i in range(1, last // 2 + 1):
        count += 1 + count_sequences(n + i, i, memo)
    memo[last] = count
    return count

import math

def count_coprime_pairs(x0: int, y0: int) -> int:
    if x0 <= 0 or y0 <= 0:
        raise ValueError("Both x0 and y0 must be positive integers")
    if y0 % x0 != 0:
        return 0

    count = 0
    quotient = y0 // x0
    for a in range(1, int(math.sqrt(quotient)) + 1):
        if quotient % a == 0:
            b = quotient // a
            if math.gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder:
        return ""

    root = postorder[-1]
    root_index = inorder.index(root)

    left_inorder = inorder[:root_index]
    right_inorder = inorder[root_index + 1:]

    left_postorder = postorder[:len(left_inorder)]
    right_postorder = postorder[len(left_inorder):-1]

    return root + preorder_traversal(left_inorder, left_postorder) + preorder_traversal(right_inorder, right_postorder)

