    opponent_score = 0

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1
        else:
            raise ValueError("Invalid point character. Only 'W' and 'L' are allowed.")

        if abs(player_score - opponent_score) >= 2 and ((player_score >= system) or (opponent_score >= system)):
            scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    if player_score > 0 or opponent_score > 0:
        scores.append(f"{player_score}:{opponent_score}")

    return scores

def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("Input must be a non-negative integer")
    if n == 0:
        return 1

    catalan = [0] * (n + 1)
    catalan[0] = 1

    for i in range(1, n + 1):
