def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    if l <= 0:
        return 0

    remaining_trees = l
    cleared_areas = set()

    for start, end in areas:
        if start < 0 or end >= l:
            raise ValueError("Area out of bounds")
        for i in range(start, end + 1):
            if i not in cleared_areas:
                cleared_areas.add(i)
                remaining_trees -= 1

    return remaining_trees

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Create a 2D DP table where dp[i][j] represents the maximum value achievable with the first i herbs and a time limit of j
    dp = [[0] * (T + 1) for _ in range(M + 1)]

    # Iterate through each herb
    for i in range(1, M + 1):
        time, value = herbs[i - 1]
        # Iterate through each possible time limit from 0 to T
        for j in range(T + 1):
            # If the current time limit is less than the time required for the herb, take the value from the previous herb
            if j < time:
                dp[i][j] = dp[i - 1][j]
            else:
                # Otherwise, take the maximum of not picking the herb or picking the herb and adding its value
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - time] + value)

    # The answer is the maximum value achievable with all herbs and the given time limit
    return dp[M][T]

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            for k in range(min(a[i - 1], j) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    key_length = len(key)
    key_as_int = [ord(i) for i in key.upper()]
    ciphertext_int = [ord(i) for i in ciphertext.upper()]
    plaintext = []

    for i in range(len(ciphertext_int)):
        key_val = key_as_int[i % key_length]
        plain_int = (ciphertext_int[i] - key_val + 26) % 26
        plaintext.append(chr(plain_int + 65))

    return ''.join(plaintext).lower()

