def jinjin_savings_plan(budgets: List[int]) -> int:
    if len(budgets) != 12:
        raise ValueError("The budgets list must contain exactly 12 integers.")

    initial_pocket_money = 300
    interest_rate = 0.20
    total_savings = 0

    for month, budget in enumerate(budgets, start=1):
        if budget >= initial_pocket_money:
            return -month

        if initial_pocket_money - budget >= 100:
            savings = 100 * ((initial_pocket_money - budget) // 100)
