    return int(total_savings)

def minimum_students_to_leave(heights):
    n = len(heights)
    if n < 3:
        return n

    # Initialize arrays to store the length of the longest increasing subsequence ending at each index
    lis = [1] * n

    # Compute the LIS values
    for i in range(1, n):
        for j in range(0, i):
            if heights[i] > heights[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    # Initialize arrays to store the length of the longest decreasing subsequence starting at each index
    lds = [1] * n

    # Compute the LDS values
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if heights[i] > heights[j] and lds[i] < lds[j] + 1:
                lds[i] = lds[j] + 1

    # Find the maximum value of (lis[i] + lds[i] - 1) for all i
    max_choir_length = 0
    for i in range(n):
        max_choir_length = max(max_choir_length, lis[i] + lds[i] - 1)

    # The minimum number of students to leave is the total number of students minus the maximum choir length
    return n - max_choir_length

def min_groups(w, n, prices):
    prices.sort()
    left, right = 0, 0
    groups = 0

    while left < n:
        if prices[left] + prices[right] <= w:
            left += 1
        right += 1
        if left == right:
            groups += 1
            left = right

    return groups

